const { chromium } = require('@playwright/test');

(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await ctx.newPage();
  const reqs = [];
  page.on('request', r => { if (r.url().includes('/api/')) reqs.push(r.method() + ' ' + r.url()); });
  const errs = [];
  page.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });

  // 1) housing page
  await page.goto('http://localhost:8095/#/pages/housing/index', { waitUntil: 'networkidle', timeout: 30000 }).catch(e => console.log('goto-err', e.message));
  await page.waitForTimeout(1500);
  let body = await page.evaluate(() => document.body.innerText).catch(() => '');
  console.log('=== housing has 马上办 card? ===', /马上办/.test(body));
  console.log('=== housing has 公共收益? ===', /公共收益/.test(body));

  // 2) navigate directly to immediate-stats
  await page.goto('http://localhost:8095/#/page-query/immediate-stats', { waitUntil: 'networkidle', timeout: 30000 }).catch(e => console.log('goto2-err', e.message));
  await page.waitForTimeout(2500);
  body = await page.evaluate(() => document.body.innerText).catch(() => '');
  console.log('=== immediate-stats network-fail? ===', /连接服务器超时|点击屏幕重试/.test(body));
  console.log('=== immediate-stats body snippet ===');
  console.log(body.slice(0, 300));
  console.log('=== api requests (last 8) ===');
  console.log(reqs.slice(-8).join('\n') || '(none)');
  console.log('=== console errors ===');
  console.log(errs.slice(0, 8).join('\n') || '(none)');
  await browser.close();
})();
